    x = observation.get("self", {}).get("position", {}).get("x", 0)
    y = observation.get("self", {}).get("position", {}).get("y", 0)

    # Default movement toward center-ish if available
    center_x = observation.get("arena", {}).get("width", 0) // 2
    center_y = observation.get("arena", {}).get("height", 0) // 2

    # Initialize preferred move
    dx = 0
    dy = 0

    # Attempt to move toward center for robustness
    if center_x is not None and isinstance(center_x, int):
        if x < center_x:
            dx = 1
        elif x > center_x:
            dx = -1
    if center_y is not None and isinstance(center_y, int):
        if y < center_y:
            dy = 1
        elif y > center_y:
            dy = -1

    # Defensive buffer to avoid illegal moves if near boundaries
    max_dx = observation.get("arena", {}).get("max_dx", 0)
    max_dy = observation.get("arena", {}).get("max_dy", 0)
    if max_dx and dx > max_dx:
        dx = max(-1, min(1, dx))
    if max_dy and dy > max_dy:
        dy = max(-1, min(1, dy))

    # If no movement decided, pick a tiny random-ish safe alternative using deterministic rule
    if dx == 0 and dy == 0:
        # Scan nearby cells for potential resource or avoidance of threat
        enemies = observation.get("enemies", [])
        resources = observation.get("resources", [])
        # If there is a nearby resource, try to move toward it
        best_rx, best_ry, best_dist = None, None, None
        for res in resources:
            rx = res.get("position", {}).get("x", x)
            ry = res.get("position", {}).get("y", y)
            dist = abs(rx - x) + abs(ry - y)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best_rx, best_ry = rx, ry
        if best_rx is not None:
            if best_rx > x:
                dx = 1
            elif best_rx < x:
                dx = -1
            if best_ry > y:
                dy = 1
            elif best_ry < y:
                dy = -1

        # If still no direction, avoid threats by stepping away from nearest enemy
        if dx == 0 and dy == 0:
            if enemies:
                ex = enemies[0].get("position", {}).get("x", x)
                ey = enemies[0].get("position", {}).get("y", y)
                if ex > x:
                    dx = -1
                elif ex < x:
                    dx = 1
                if ey > y:
                    dy = -1
                elif ey < y:
                    dy = 1

    # Bound to -1, 0, 1
    dx = -1 if dx < -1 else 1 if dx > 1 else dx
    dy = -1 if dy < -1 else 1 if dy > 1 else dy

    return [dx, dy]

